            if (node.parent === this)
                continue;
            node.parent?.remove(node);
            node.parent = this;
            this.children.push(node);
            node.attachRegistry(this.registry);
            node.markWorldDirty();
            this.markSubtreeDirtyUp();
            node.emit('added', { node, parent: this });
