                this.worldMatrix.multiplyMatrices(this.parent.worldMatrix, this.localMatrix);
            else
                this.worldMatrix.copy(this.localMatrix);
            this.worldVisible = this.visible && (this.parent?.worldVisible ?? true);
            this.worldDirty = false;
            this.worldVersion += 1;
            if (stats)
                stats.updated += 1;
